"""
Regression test for: frozen attrs exception classes raise FrozenInstanceError
when Python's exception machinery tries to set __traceback__ (e.g. when
raised inside a context manager or when __traceback__ is manually
re-assigned).
"""
from contextlib import contextmanager

import pytest

import attr
import attrs


@contextmanager
def do_nothing():
    yield


def test_frozen_exception_traceback_can_be_reassigned():
    @attrs.frozen
    class MyException(Exception):
        pass

    e = MyException()

    # Directly setting __traceback__ should not raise FrozenInstanceError.
    e.__traceback__ = e.__traceback__


def test_frozen_exception_raised_in_context_manager_does_not_blow_up():
    @attr.s(frozen=True, auto_exc=True)
    class MyException(Exception):
        pass

    caught = None
    try:
        with do_nothing():
            raise MyException()
    except MyException as e:
        caught = e
        # This assignment happens internally when the exception propagates
        # through the context manager; it must not raise.
        e.__traceback__ = e.__traceback__

    assert caught is not None
    assert caught.__traceback__ is not None


def test_frozen_exception_still_frozen_for_other_attributes():
    @attrs.frozen
    class MyException(Exception):
        x = attrs.field(default=1)

    e = MyException()

    with pytest.raises(attr.exceptions.FrozenInstanceError):
        e.x = 2

"""
Regression test for bug: parse_wheel_filename / parse_sdist_filename should
raise InvalidWheelFilename / InvalidSdistFilename (not InvalidVersion) when
the filename contains a bogus version string.
"""

import pytest

from packaging.utils import (
    InvalidSdistFilename,
    InvalidWheelFilename,
    parse_sdist_filename,
    parse_wheel_filename,
)
from packaging.version import InvalidVersion


def test_parse_wheel_filename_bogus_version_raises_invalid_wheel_filename():
    with pytest.raises(InvalidWheelFilename):
        parse_wheel_filename("foobar-1.x-py3-none-any.whl")


def test_parse_wheel_filename_bogus_version_does_not_raise_invalid_version():
    try:
        parse_wheel_filename("foobar-1.x-py3-none-any.whl")
    except InvalidVersion:
        pytest.fail(
            "parse_wheel_filename raised InvalidVersion instead of "
            "InvalidWheelFilename"
        )
    except InvalidWheelFilename:
        pass


def test_parse_sdist_filename_bogus_version_raises_invalid_sdist_filename():
    with pytest.raises(InvalidSdistFilename):
        parse_sdist_filename("foo-1.x.tar.gz")


def test_parse_sdist_filename_bogus_version_does_not_raise_invalid_version():
    try:
        parse_sdist_filename("foo-1.x.tar.gz")
    except InvalidVersion:
        pytest.fail(
            "parse_sdist_filename raised InvalidVersion instead of "
            "InvalidSdistFilename"
        )
    except InvalidSdistFilename:
        pass

"""
Regression test for bug: Version.replace() does not preserve the subclass
type of the instance it is called on; it always returns a plain Version
instance instead of an instance of the subclass.
"""

from semver import Version


class SemVerWithVPrefix(Version):
    @classmethod
    def parse(cls, version, optional_minor_and_patch=False):
        if version[0] not in ("v", "V"):
            raise ValueError("must start with v or V")
        return super().parse(version[1:], optional_minor_and_patch=True)

    def __str__(self):
        return "v" + super().__str__()


def test_replace_preserves_subclass_type():
    version = SemVerWithVPrefix.parse("v1.1.0")
    dev_version = version.replace(prerelease="dev.0")

    assert isinstance(dev_version, SemVerWithVPrefix), (
        f"Expected replace() to return an instance of "
        f"SemVerWithVPrefix, got {type(dev_version)}"
    )
    assert str(dev_version) == "v1.1.0-dev.0"

